\begin{definition}[d'Alembert's formula]
\label{def:dalembert-formula}


\group{Wave Equation}


For $g,h:\R\to\R$, d'Alembert's solution is
$$u(x,t):=\frac12[g(x+t)+g(x-t)]
+\frac12\int_{x-t}^{x+t}h(y)\,dy.$$
\end{definition}

